package com.aadil.ecommerce.services;import com.aadil.ecommerce.UserRole;import com.aadil.ecommerce.dtos.LoginRequestDTO;import com.aadil.ecommerce.dtos.UserRequestDTO;import com.aadil.ecommerce.dtos.UserResponseDTO;import com.aadil.ecommerce.entities.UserEntity;import com.aadil.ecommerce.enums.UserSortDirection;import com.aadil.ecommerce.enums.UserSortField;import com.aadil.ecommerce.exceptions.InvalidCredentialException;import com.aadil.ecommerce.exceptions.UserAlreadyExistsException;import com.aadil.ecommerce.repositories.UserRepository;import com.aadil.ecommerce.responses.PaginatedResponse;import com.aadil.ecommerce.responses.UserLoginResponse;import com.aadil.ecommerce.security.JwtUtility;import jakarta.validation.constraints.NotNull;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.Page;import org.springframework.data.domain.PageRequest;import org.springframework.data.domain.Pageable;import org.springframework.data.domain.Sort;import org.springframework.security.authentication.AuthenticationProvider;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.AuthenticationException;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.security.core.userdetails.UserDetailsService;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import java.io.IOException;import java.util.List;@Service@RequiredArgsConstructorpublic class UserService {    private final PasswordEncoder passwordEncoder;    private final UserRepository userRepository;    private final JwtUtility jwtUtility;    private final AuthenticationProvider authenticationProvider;    private final UserDetailsService userDetailsService;    private UserResponseDTO mapToDTO (UserEntity user){        System.out.println("ID: " + user.getId());        System.out.println("NAME: " + user.getName());        System.out.println("EMAIL: " + user.getEmail());        System.out.println("ROLE: " + user.getRole());        return new UserResponseDTO(user.getId(),user.getName(),user.getEmail(),user.getRole());    }    public UserResponseDTO registerUser (UserRequestDTO dto){        String email = dto.getEmail().trim().toLowerCase();        if (userRepository.findByEmail(email).isPresent()){            throw new UserAlreadyExistsException("USER_ALREADY_REGISTERED");        }        String hashedPassword = passwordEncoder.encode(dto.getPassword());        UserEntity user = new UserEntity();        user.setName(dto.getName());        user.setEmail(email);        user.setPassword(hashedPassword);        user.setRole(UserRole.USER);       UserEntity savedUser = userRepository.save(user);       return mapToDTO(savedUser);    }    public UserLoginResponse userLogin (LoginRequestDTO dto) {        String email = dto.getEmail().trim().toLowerCase();        try {            authenticationProvider.authenticate(new UsernamePasswordAuthenticationToken(email,dto.getPassword()));            UserDetails userDetails = userDetailsService.loadUserByUsername(email);            String token =  jwtUtility.generateToken(userDetails);            return new UserLoginResponse(token);        }        catch (AuthenticationException e){            throw new InvalidCredentialException("Invalid Credentials, Check your Email OR password");        }    }    public PaginatedResponse<List<UserResponseDTO>> getAllUsers (String search, int pageNumber, int size, UserSortField sortField, UserSortDirection sortDirection){        if (search != null && search.isBlank()){           search =  search.trim();        }        if (pageNumber < 0){            throw new InvalidCredentialException("PageNumber should NOT be 0");        }        if (pageNumber > 30){            throw new InvalidCredentialException("PageNumber should NOT exceed 30");        }        if (size < 1){            throw new InvalidCredentialException("Size should NOT be below 1");        }        if (size > 30){            throw new InvalidCredentialException("Size should NOT exceed 30");        }        if (sortField == null){            sortField = UserSortField.ID;        }        if (sortDirection == null){            sortDirection = UserSortDirection.ASC;        }        Sort.Direction direction = sortDirection == UserSortDirection.ASC?                Sort.Direction.ASC:Sort.Direction.DESC;        Sort sort = Sort.by(new Sort.Order(direction,sortField.getUserSortField()));        Pageable pageable = PageRequest.of(pageNumber,size,sort);        Page<UserEntity> user;        if (search == null || search.isBlank()){            user = userRepository.findAll(pageable);        }        else {            user = userRepository.findByEmailContainingIgnoreCaseOrNameContainingIgnoreCase(search,search,pageable);        }        List<UserResponseDTO> contents = user.getContent().stream().map(this::mapToDTO).toList();        return new PaginatedResponse<>(contents,user.getNumber(),user.getSize(),user.getTotalElements(),user.getTotalPages(),user.isLast());    }}